mapper.insert:
INSERT INTO region (
    region_id,
    region_name,
    parent_region_id
) VALUES (
    #{regionId},
    #{regionName},
    #{parentRegionId}
)
ON DUPLICATE KEY UPDATE
    region_name = VALUES(region_name),
    parent_region_id = VALUES(parent_region_id);

INSERT INTO place_image (
    place_id,
    image_url,
    sort_order
) VALUES (
    #{placeId},
    #{imageUrl},
    #{sortOrder}
);

mapper.select:
SELECT COUNT(*)
FROM place
WHERE region_id = #{regionId}

SELECT COUNT(*)
FROM place
WHERE region_id = #{regionId}
AND place_type = #{placeType}
